def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

def char_freq(s):
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    return counts

def safe_div(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        return None
